import styles from "./footer.module.less";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";
import Link from "@/core/components/primitives/link/link";
import { multipleClassNames } from "@/core/helpers";
import { hasImageFileUrl } from "../../../helpers/footer-helper";

export type FooterImageFile = {
  url?: string;
};

export type FooterImage = {
  file?: FooterImageFile;
  gatsbyImageData?: IGatsbyImageData;
};

export type FooterLink = {
  id?: string;
  title?: string;
  slug?: string;
  externalUrl?: string;
  linkIcon?: string;
  icon?: string;
  image?: FooterImage;
};

export type FooterAddressLink = {
  slug?: string;
};

export type FooterBackground = {
  backgroundPattern?: {
    file?: {
      url?: string;
    };
  };
};

export type SiteConfiguration = {
  footerBackground?: FooterBackground;
  footerLogo?: FooterImage;
  footerLinks?: FooterLink[];
  additionalFooterLinks?: FooterLink[];
  footerPhoneNumber?: string;
  footerAddress?: string;
  footerAddressLink?: FooterAddressLink;
  footerEmail?: string;
  footerSocialMediaTitle?: string;
  footerSocialMediaLinks?: FooterLink[];
  footerOrganizationLinks?: FooterLink[];
  footerParksAndResortsLink?: FooterLink;
  footerParksLinks?: FooterLink[];
};

type FooterProps = {
  siteConfig: SiteConfiguration;
};

const Footer = ({ siteConfig }: FooterProps) => {
  const backgroundPatternUrl = siteConfig?.footerBackground?.backgroundPattern?.file?.url;
  const logo = siteConfig?.footerLogo;
  const footerLinks = siteConfig?.footerLinks ?? [];
  const additionalFooterLinks = siteConfig?.additionalFooterLinks ?? [];
  const phoneNumber = siteConfig?.footerPhoneNumber;
  const address = siteConfig?.footerAddress;
  const addressLink = siteConfig?.footerAddressLink?.slug;
  const email = siteConfig?.footerEmail;
  const socialMediaTitle = siteConfig?.footerSocialMediaTitle;
  const socialMediaLinks = siteConfig?.footerSocialMediaLinks ?? [];
  const organizationLinks = siteConfig?.footerOrganizationLinks ?? [];
  const parksAndResortsLink = siteConfig?.footerParksAndResortsLink;
  const parksLinks = siteConfig?.footerParksLinks ?? [];

  const backgroundStyle = backgroundPatternUrl ? { backgroundImage: `url(${backgroundPatternUrl})` } : {};

  return (
    <div style={backgroundStyle} className={styles.footer}>
      <div className={multipleClassNames(styles.footerUpperWrapper, "block--max-width-narrow")}>
        {logo && (
          <div className={styles.logoWrapper}>
            {logo.gatsbyImageData ? (
              <GatsbyImage image={logo.gatsbyImageData} alt="Footer logo" />
            ) : logo.file?.url ? (
              <img src={logo.file.url} alt="Footer logo" />
            ) : null}
          </div>
        )}

        {footerLinks.length > 0 && (
          <ul className={multipleClassNames(styles.list, styles.linksList)}>
            {footerLinks.map((link) => (
              <li key={link?.id} className={multipleClassNames(styles.listItem, styles.linkItem)}>
                <Link
                  className={multipleClassNames("p_small", styles.footerLink, styles.linkItemLink)}
                  internalLink={link?.slug}
                  externalLink={link?.externalUrl}
                  title={link?.title}
                >
                  {link?.title}
                </Link>
              </li>
            ))}
          </ul>
        )}

        <div className={styles.divider}></div>

        {additionalFooterLinks.length > 0 && (
          <ul className={multipleClassNames(styles.list, styles.additionalLinksList)}>
            {additionalFooterLinks.map((link) => (
              <li key={link?.id} className={multipleClassNames(styles.listItem, styles.additionalLinkItem)}>
                <Link
                  className={multipleClassNames(
                    "p_tiny",
                    styles.footerLink,
                    styles.additionalLinks,
                    styles.additionalLinkItemLink,
                  )}
                  internalLink={link?.slug}
                  externalLink={link?.externalUrl}
                  title={link?.title}
                >
                  {link?.title}
                </Link>
              </li>
            ))}
          </ul>
        )}

        <address>
          <ul className={multipleClassNames(styles.list, styles.contactList)}>
            {phoneNumber && (
              <li className={multipleClassNames("p_tiny", styles.listItem, styles.contactListItem)}>
                <span className={multipleClassNames("icon-phone-android", styles.contactIcon)}></span>

                <Link externalLink={`tel:${phoneNumber}`} title={phoneNumber}>
                  {phoneNumber}
                </Link>
              </li>
            )}
            {address && (
              <li className={multipleClassNames("p_tiny", styles.listItem, styles.contactListItem)}>
                <span className={multipleClassNames("icon-location", styles.contactIcon)}></span>

                <Link internalLink={addressLink} title={address}>
                  <span>{address}</span>
                </Link>
              </li>
            )}
            {email && (
              <li className={multipleClassNames("p_tiny", styles.listItem, styles.contactListItem)}>
                <span className={multipleClassNames("icon-send", styles.contactIcon)}></span>

                <Link externalLink={`mailto:${email}`} title={email}>
                  {email}
                </Link>
              </li>
            )}
          </ul>
        </address>

        <div className={styles.socialMediaWrapper}>
          {socialMediaTitle && (
            <span className={multipleClassNames("p_tiny", styles.socialMediaTitle)}>{socialMediaTitle}</span>
          )}
          {socialMediaLinks.length > 0 && (
            <ul className={multipleClassNames(styles.list, styles.socialMediaList)}>
              {socialMediaLinks.map((link) => (
                <li
                  key={link?.id}
                  className={multipleClassNames(styles.listItem, styles.socialMediaListItem, styles.listItem_flowing)}
                >
                  <Link
                    aria-label={link?.title || "Social Media Link"}
                    externalLink={link?.externalUrl}
                    title={link?.title}
                    openInNewTab
                    className={multipleClassNames(styles.socialMediaListLink, styles.socialMediaListLink)}
                  >
                    <span className={link?.linkIcon ?? link?.icon ?? ""}></span>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>

        {organizationLinks.length > 0 && (
          <ul className={multipleClassNames(styles.organizationList)}>
            {organizationLinks.map((link) => (
              <li key={link?.id} className={styles.organizationListItem}>
                <Link
                  externalLink={link?.externalUrl ?? ""}
                  openInNewTab
                  title={link?.title}
                  className={styles.organizationLink}
                >
                  {hasImageFileUrl(link) && <img src={link.image.file.url} alt={link.title ?? ""} />}
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className={styles.parksWrapper}>
        <div className="block--max-width-narrow">
          {parksAndResortsLink && (
            <Link
              externalLink={parksAndResortsLink.externalUrl ?? ""}
              openInNewTab
              className={styles.parksLogo}
              title={parksAndResortsLink.title}
            >
              {hasImageFileUrl(parksAndResortsLink) && (
                <img
                  loading="lazy"
                  src={parksAndResortsLink.image.file.url}
                  alt={parksAndResortsLink.title ?? ""}
                  className={styles.parksLogo}
                />
              )}
            </Link>
          )}

          {parksLinks.length > 0 && (
            <ul className={multipleClassNames(styles.list_centered, styles.parksList)}>
              {parksLinks.map((link) => (
                <li key={link?.id} className={multipleClassNames(styles.listItem_flowing, styles.parksListItem)}>
                  {!link?.externalUrl && <ParkLinksImage link={link} />}
                  {link?.externalUrl && (
                    <Link externalLink={link?.externalUrl ?? ""} openInNewTab title={link?.title}>
                      <ParkLinksImage link={link} />
                    </Link>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
};

const ParkLinksImage = ({ link }: { link: NonNullable<SiteConfiguration["footerParksLinks"]>[0] }) => {
  return (
    hasImageFileUrl(link) && (
      <img className={styles.parksListImage} loading="lazy" src={link.image.file.url} alt={link.title ?? ""} />
    )
  );
};

export default Footer;
